                author: "Delia Owens",
                category: "Fiction",
                price: 12.49,
                rating: 4.7,
                image: "https://images.unsplash.com/photo-1629992101753-56d196c8aabb?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"
            },
            {
                id: 3,
                title: "Atomic Habits",
                author: "James Clear",
                category: "Self-Help",
                price: 16.99,
                rating: 4.8,
                image: "https://images.unsplash.com/photo-1541963463532-d68292c34b19?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"
            },
            {
                id: 4,
                title: "The Midnight Library",
                author: "Matt Haig",
                category: "Fiction",
                price: 13.25,
                rating: 4.4,
                image: "https://images.unsplash.com/photo-1495446815901-a7297e633e8d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"
            },
            {
                id: 5,
                title: "Project Hail Mary",
                author: "Andy Weir",
                category: "Sci-Fi",
                price: 18.95,
                rating: 4.9,
                image: "https://images.unsplash.com/photo-1512820790803-83ca734da794?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"
            },
            {
                id: 6,
                title: "Educated: A Memoir",
                author: "Tara Westover",
                category: "Biography",
                price: 15.50,
                rating: 4.7,
                image: "https://images.unsplash.com/photo-1531346878377-a5be20888e57?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"
            },
            {
                id: 7,
                title: "The Four Winds",
                author: "Kristin Hannah",
                category: "Historical Fiction",
                price: 12.99,
                rating: 4.6,
                image: "https://images.unsplash.com/photo-1519681393784-d120267933ba?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"
            },
            {
                id: 8,
                title: "The Last Thing He Told Me",
                author: "Laura Dave",
                category: "Thriller",
                price: 11.99,
                rating: 4.3,
                image: "https://images.unsplash.com/photo-1531901599638-a89b5d000a19?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"
            }
        ];

        // Cart state
        let cart = [];
        let cartTotal = 0;

        // DOM elements
        const productsGrid = document.getElementById('products-grid');
        const cartIcon = document.getElementById('cart-icon');
        const cartModal = document.getElementById('cart-modal');
        const overlay = document.getElementById('overlay');
        const closeCart = document.getElementById('close-cart');
        const continueShopping = document.getElementById('continue-shopping');
        const cartItems = document.getElementById('cart-items');
        const cartTotalPrice = document.getElementById('cart-total-price');
        const cartCount = document.querySelector('.cart-count');

        // Initialize the store
        function initStore() {
            renderBooks();
            setupEventListeners();
            updateCartCount();
        }

        // Render books to the page
        function renderBooks() {
            productsGrid.innerHTML = '';

            books.forEach(book => {
                const bookCard = document.createElement('div');
                bookCard.className = 'product-card';

                // Generate star rating HTML
                let starsHtml = '';
                for (let i = 1; i <= 5; i++) {
                    if (i <= Math.floor(book.rating)) {
                        starsHtml += '<i class="fas fa-star"></i>';
                    } else if (i === Math.ceil(book.rating) && !Number.isInteger(book.rating)) {
                        starsHtml += '<i class="fas fa-star-half-alt"></i>';
                    } else {
                        starsHtml += '<i class="far fa-star"></i>';
                    }
                }

                bookCard.innerHTML = `
                    <div class="product-image" style="background-image: url('${book.image}')"></div>
                    <div class="product-info">
                        <div class="product-category">${book.category}</div>
                        <h3 class="product-title">${book.title}</h3>
                        <div class="product-author">by ${book.author}</div>
                        <div class="rating">
                            ${starsHtml} ${book.rating}
                        </div>
                        <div class="product-price">
                            <div class="price">$${book.price.toFixed(2)}</div>
                            <button class="add-to-cart" data-id="${book.id}">
                                <i class="fas fa-plus"></i>
                            </button>
                        </div>
                    </div>
                `;

                productsGrid.appendChild(bookCard);
            });
        }

        // Set up event listeners
        function setupEventListeners() {
            // Add to cart buttons
            document.querySelectorAll('.add-to-cart').forEach(button => {
                button.addEventListener('click', (e) => {
                    const bookId = parseInt(e.currentTarget.dataset.id);
                    addToCart(bookId);
                });
            });

            // Cart icon click
            cartIcon.addEventListener('click', () => {
                cartModal.classList.add('active');
                overlay.classList.add('active');
                document.body.style.overflow = 'hidden';
            });

            // Close cart
            closeCart.addEventListener('click', closeCartModal);
            overlay.addEventListener('click', closeCartModal);
            continueShopping.addEventListener('click', closeCartModal);
        }

        // Close cart modal
        function closeCartModal() {
            cartModal.classList.remove('active');
            overlay.classList.remove('active');
            document.body.style.overflow = 'auto';
        }

        // Add item to cart
        function addToCart(bookId) {
            const book = books.find(b => b.id === bookId);

            // Check if book is already in cart
            const existingItem = cart.find(item => item.id === bookId);

            if (existingItem) {
                existingItem.quantity += 1;
            } else {
                cart.push({
                    id: book.id,
                    title: book.title,
                    author: book.author,
                    price: book.price,
                    image: book.image,
                    quantity: 1
                });
            }

            updateCartCount();
            renderCartItems();

            // Show success notification
            showNotification(`${book.title} added to cart!`);
        }

        // Update cart count display
        function updateCartCount() {
            const count = cart.reduce((total, item) => total + item.quantity, 0);
            cartCount.textContent = count;
        }

        // Render cart items
        function renderCartItems() {
            cartItems.innerHTML = '';

            if (cart.length === 0) {
                cartItems.innerHTML = '<p style="text-align: center; padding: 2rem;">Your cart is empty</p>';
                cartTotalPrice.textContent = '$0.00';
                return;
            }

            cartTotal = 0;

            cart.forEach(item => {
                const itemTotal = item.price * item.quantity;
                cartTotal += itemTotal;

                const cartItem = document.createElement('div');
                cartItem.className = 'cart-item';
                cartItem.innerHTML = `
                    <div class="cart-item-image" style="background-image: url('${item.image}')"></div>
                    <div class="cart-item-details">
                        <div class="cart-item-title">${item.title}</div>
                        <div class="cart-item-author">by ${item.author}</div>
                        <div class="cart-item-price">$${item.price.toFixed(2)}</div>
                        <div class="cart-item-actions">
                            <button class="quantity-btn minus" data-id="${item.id}">-</button>
                            <span class="quantity">${item.quantity}</span>
                            <button class="quantity
